// Every wall has a plant: the defect it guards, put back into a fresh copy of the frozen tree, which must turn that wall RED by its own line. A check is proven by its control.
//   node plants.mjs <frozen web dir> [--only=a,b or a wall's name] [--check] [--list] [--engine=chromium] [--gate=dir with the clean walls' json] [--who=name]
// --check only applies every edit to the frozen tree and lists what's STALE: no browser, no lock.
// A fresh copy each (an APFS clone: cp -c, no disk), served on its own port, the wall run as it ships under heavy.sh, one at a time, the lock released between.
// STALE: an edit no longer applies: the code moved: rewrite the plant against the new code, never drop it.
// Where the wall is already RED on the clean tree, a plant can't turn it red: it's read by `reading`, a number in the wall's own line that must get worse. Said plainly as CAUGHT (a red wall, the number moved). It proves the wall can see the defect, not that the wall is met.
// plants.d/*.mjs export more plants (an array as default), for other owners' checks. Each is { name, why, edits, test, only, catches, reading?, engine? }.
//   edits: [{ file, old, new }] exact text, once; or { file, all: true, old, new } every place; or { file, fn: (text) => text }; or { file, write: text } for a new file.
import fs from 'fs'; import path from 'path'; import http from 'http'; import { spawnSync, spawn } from 'child_process'; import { fileURLToPath, pathToFileURL } from 'url'; import os from 'os';
const HERE = path.dirname(fileURLToPath(import.meta.url));
const J = (f) => (t) => { const o = JSON.parse(t); f(o); return JSON.stringify(o); };   // an edit of world.json
const solids = (d) => [...d.colliders, ...Object.values(d.col_kinds || {}).flat()];     // the big map keeps most solids per kind, in col_kinds, and places them with the instances
const inject = (code) => ({ file: 'js/main.js', old: 'G.frame = frame;', new: `G.frame = frame;\n  ${code}` });
const each = (code) => ({ file: 'js/main.js', old: 'function frame(dt) {', new: `function frame(dt) {\n  ${code}` });
// a button that looks right and does nothing: the page's handlers land on a hidden twin
const deadButton = (id, wall, name) => ({ name: `c1_${name}_dead`, why: `the ${name} button does nothing`, edits: [{ file: 'index.html', old: `id="${id}"`, new: `id="${id}Live" style="display:none!important"` }, { file: 'index.html', old: '<div id="pauseB"', new: `<div class="btn" id="${id}">${name}</div><div id="pauseB"` }, { file: 'js/ui.js', old: "const hold = (id, name, isHold) => {\n    const b = $(id);", new: `const hold = (id, name, isHold) => {\n    const b = $(id === '${id}' ? '${id}Live' : id);` }], test: 'input', only: wall, catches: new RegExp(`^FAIL ${wall.replace('.', '\\.')} `, 'm') });

