if (gateDir) fs.writeFileSync(path.join(gateDir, 'plants.json'), JSON.stringify(done, null, 1));
fs.rmSync(base, { recursive: true, force: true });
console.log(`PLANTS ${caught} caught, ${missed} missed, ${stale} stale, of ${done.length}, in ${Math.round((Date.now() - t0) / 1000)} s`);
process.exit(missed || stale ? 1 : 0);
